INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch02$PT159-S3-Q25$batch02$, 159, 3, 25, $batch02$Flaw$batch02$, $batch02$Paleontologist: Most biologists accept that birds evolved from dinosaurs known as maniraptors. Some biologists have not accepted this theory, because the oldest known bird fossils predate the oldest known maniraptor fossils by several million years. This reasoning is misguided, however; the fact that no maniraptor fossils of a certain age have been discovered hardly rules out the possibility that such fossils exist.$batch02$, $batch02$The paleontologist’s argument is most vulnerable to criticism on which one of the following grounds?$batch02$, $batch02$E$batch02$, true, $batch02$Batch 02 approved 2026-10-01; question text from local bank.$batch02$ FROM lr_sections s WHERE s.preptest=159 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT159-S3-Q25$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$A$batch02$, $batch02$It overlooks the possibility that even if a particular argument against a theory is misguided, that theory may nonetheless be untrue.$batch02$, $batch02$Not an Objection$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT159-S3-Q25$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$A$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$B$batch02$, $batch02$It fails to address adequately the possibility that even if maniraptors existed before the first birds did, there may not be any maniraptor fossils older than the oldest known bird fossils.$batch02$, $batch02$Strengthens, if anything$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT159-S3-Q25$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$B$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$C$batch02$, $batch02$It takes for granted that if there are any maniraptor fossils older than the oldest known bird fossils, this itself proves that birds evolved from maniraptors.$batch02$, $batch02$Not Assumed$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT159-S3-Q25$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$C$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$D$batch02$, $batch02$It overlooks the possibility that there may be substantial evidence that birds did not evolve from maniraptors, but that this evidence may be unrelated to the ages of any known or unknown bird and maniraptor fossils.$batch02$, $batch02$Out of Scope$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT159-S3-Q25$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$D$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$E$batch02$, $batch02$It fails to address adequately the possibility that it can be reasonable to refuse to accept a theory solely on the grounds that the evidence yet discovered for the theory appears to be insufficient.$batch02$, $batch02$Correct$batch02$, true FROM lr_questions q WHERE q.qid=$batch02$PT159-S3-Q25$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$E$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT159-S3-Q25$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Some biologists' position$batch02$, $batch02$They have *not accepted* the theory, because no maniraptor fossils old enough have been found.$batch02$), (1, $batch02$Paleontologist's conclusion$batch02$, $batch02$That reasoning is misguided.$batch02$), (2, $batch02$Paleontologist's evidence$batch02$, $batch02$Not finding such fossils does not rule out that they exist.$batch02$), (3, $batch02$Evaluate$batch02$, $batch02$The skeptics never said older maniraptor fossils do not exist. They declined to accept the theory until the evidence supports it. The paleontologist answers a stronger claim: that the fossils cannot exist. A jury that says "not proven" is not saying "innocent." Withholding belief because the evidence is thin can be perfectly reasonable even if more evidence might turn up later.$batch02$), (4, $batch02$Goal$batch02$, $batch02$Look for the point that refusing to accept a theory on thin evidence can be reasonable.$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT159-S3-Q25$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$The paleontologist never says the theory is true because the skeptics' argument fails. He says only that their reasoning is misguided. So this does not catch any move he makes.$batch02$), ($batch02$B$batch02$, $batch02$If older maniraptors could have lived without leaving older fossils, the missing fossils are even weaker evidence against the theory. That supports the paleontologist.$batch02$), ($batch02$C$batch02$, $batch02$The paleontologist does not claim older fossils would prove the theory. He only says their absence does not disprove it.$batch02$), ($batch02$D$batch02$, $batch02$The paleontologist addresses one piece of reasoning. Other evidence against the theory would not show his response to *that* reasoning is flawed.$batch02$), ($batch02$E$batch02$, $batch02$The skeptics refuse to *accept* the theory because the evidence found so far looks insufficient. That can be reasonable even if the missing fossils might exist. The paleontologist treats their position as if it required proof that the fossils do not exist.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT159-S3-Q25$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
